{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "file",
      "type": "DiffViewerFile",
      "description": "The file to render: paths, status, binary flag, and hunks of numbered lines. Build it with parseUnifiedDiff or createDiffFile.",
      "required": true
    },
    {
      "name": "viewMode",
      "type": "'unified' | 'split'",
      "description": "'unified' shows one column with removed lines above their replacements; 'split' shows the old file on the left and the new file on the right, pairing each removed line with the added line that replaced it.",
      "default": "'unified'"
    },
    {
      "name": "language",
      "type": "string | CodeLanguage",
      "description": "Syntax-highlighting language: a built-in identifier, or a CodeBlock language value imported on its own (e.g. graphql from @astryxdesign/core/CodeBlock/languages/graphql) or made with createCodeLanguage. Defaults to one inferred from the file name or extension among the built-ins and codeLanguages; an unmatched file renders as plain text."
    },
    {
      "name": "codeLanguages",
      "type": "ReadonlyArray<CodeLanguage>",
      "description": "Language values the file name or extension may infer, such as [graphql, dockerfile]; a later entry wins. Pass the same list to every DiffViewer on a review page."
    },
    {
      "name": "hasLineNumbers",
      "type": "boolean",
      "description": "Show the old and new line-number gutters.",
      "default": "true"
    },
    {
      "name": "isWrapped",
      "type": "boolean",
      "description": "Wrap long lines instead of scrolling them horizontally. Unwrapped, line numbers and change indicators stay pinned while the code scrolls; in split view each side is its own scroller, the split stays fixed at half and half, and the two sides scroll sideways in lockstep. While code overflows sideways, sideways overscroll (elastic bounce, swipe navigation) is off.",
      "default": "false"
    },
    {
      "name": "changeIndicator",
      "type": "'classic' | 'bars' | 'none'",
      "description": "How changed lines are marked beside their code: 'classic' +/− glyphs, 'bars' (a solid bar for added lines, a dashed bar for removed lines), or 'none'. Screen readers hear \"Added\"/\"Removed\" in every mode.",
      "default": "'classic'"
    },
    {
      "name": "inlineHighlight",
      "type": "'word' | 'char' | 'none'",
      "description": "Highlight the changed words (or characters) inside each removed line and the added line that replaced it, paired as in split view. Lines that share nothing but whitespace get no inline highlight.",
      "default": "'word'"
    },
    {
      "name": "hasChangeBackground",
      "type": "boolean",
      "description": "Tint the rows of added and removed lines. Without it only the change indicator, the line numbers, and the inline highlight mark a change.",
      "default": "true"
    },
    {
      "name": "isCollapsible",
      "type": "boolean",
      "description": "Make the file header a disclosure that hides and shows the hunks. Applies when the file has a path to name the control.",
      "default": "true"
    },
    {
      "name": "isCollapsed",
      "type": "boolean",
      "description": "Controlled collapsed state. Pair with onCollapsedChange."
    },
    {
      "name": "defaultIsCollapsed",
      "type": "boolean",
      "description": "Initial collapsed state when uncontrolled.",
      "default": "false"
    },
    {
      "name": "onCollapsedChange",
      "type": "(isCollapsed: boolean) => void",
      "description": "Called with the next collapsed state when the header is toggled."
    },
    {
      "name": "headerEnd",
      "type": "ReactNode",
      "description": "Content at the end of the file header, such as a \"Viewed\" checkbox or a file actions menu."
    },
    {
      "name": "renderLineAnnotation",
      "type": "(ref: DiffViewerLineRef) => ReactNode",
      "description": "Render content in a full-width row under a line, such as review comments; return null for lines with nothing to show. In split view the row sits under the line's own side."
    },
    {
      "name": "onLineNumberClick",
      "type": "(ref: DiffViewerLineRef, event: MouseEvent<HTMLButtonElement>) => void",
      "description": "Makes each line's number a button, for example to start a comment on that line. The button is the number the line is anchored to: the original number of a removed line, and the changed-file number of an added or unchanged line (an unchanged line's original number stays plain text). Each line number is its own Tab stop."
    },
    {
      "name": "maxHeight",
      "type": "number | string",
      "description": "Maximum height of the hunk area before it scrolls."
    },
    {
      "name": "syntaxTheme",
      "type": "SyntaxThemeDefinition",
      "description": "Per-instance syntax theme, as on CodeBlock. Without it the nearest SyntaxTheme or the theme syntax colors apply."
    },
    {
      "name": "ref",
      "type": "Ref<HTMLDivElement>",
      "description": "Ref forwarded to the root element."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
